package com.markethub.common.exception;
import com.markethub.common.api.ApiResponse; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.dao.OptimisticLockingFailureException; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler {
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiResponse<Void>> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Request validation failed");return ResponseEntity.badRequest().body(ApiResponse.failure(new ApiResponse.ApiError("VALIDATION_ERROR",m)));}
 @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiResponse<Void>> notFound(ResourceNotFoundException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ApiResponse.failure(new ApiResponse.ApiError("NOT_FOUND","The requested resource was not found")));}
 @ExceptionHandler(AccessDeniedException.class) ResponseEntity<ApiResponse<Void>> forbidden(AccessDeniedException e){return ResponseEntity.status(HttpStatus.FORBIDDEN).body(ApiResponse.failure(new ApiResponse.ApiError("FORBIDDEN","You are not authorized to access this resource")));}
 @ExceptionHandler({IllegalStateException.class,OptimisticLockingFailureException.class,DataIntegrityViolationException.class}) ResponseEntity<ApiResponse<Void>> conflict(RuntimeException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(ApiResponse.failure(new ApiResponse.ApiError("CONFLICT",e instanceof IllegalStateException?e.getMessage():"The resource conflicts with its current state")));}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ApiResponse<Void>> badRequest(IllegalArgumentException e){return ResponseEntity.badRequest().body(ApiResponse.failure(new ApiResponse.ApiError("BAD_REQUEST",e.getMessage())));}
 @ExceptionHandler(org.springframework.web.server.ResponseStatusException.class) ResponseEntity<ApiResponse<Void>> statusException(org.springframework.web.server.ResponseStatusException e){String message=e.getReason()==null?"Request could not be processed":e.getReason();return ResponseEntity.status(e.getStatusCode()).body(ApiResponse.failure(new ApiResponse.ApiError("HTTP_"+e.getStatusCode().value(),message)));}
 @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> unexpected(Exception e){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(ApiResponse.failure(new ApiResponse.ApiError("INTERNAL_ERROR","An unexpected error occurred")));}
}